"use client";

import React, { useEffect, useState } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { getCustomerHistory } from '@/lib/api';

interface CustomerDetailDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  customer: any | null;
  onEdit: () => void;
}

export function CustomerDetailDialog({ open, onOpenChange, customer, onEdit }: CustomerDetailDialogProps) {
  const [history, setHistory] = useState<any[]>([]);

  useEffect(() => {
    if (open && customer?.id) {
      (async () => {
        try {
          const h = await getCustomerHistory(customer.id);
          setHistory(h || []);
        } catch (err) {
          setHistory([]);
        }
      })();
    }
  }, [open, customer]);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle>Detalle de Cliente</DialogTitle>
          <DialogDescription>Informacion y historial de transacciones.</DialogDescription>
        </DialogHeader>

        <div className="py-2">
          <div className="mb-2"><strong>Nombre:</strong> {customer?.name}</div>
          <div className="mb-2"><strong>Documento:</strong> {customer?.document}</div>
          <div className="mb-2"><strong>Email:</strong> {customer?.email}</div>
          <div className="mb-2"><strong>Teléfono:</strong> {customer?.phone}</div>
          <div className="mb-2"><strong>Dirección:</strong> {customer?.address}</div>
          <div className="mb-4"><strong>Notas:</strong> {customer?.notes}</div>

          <div>
            <h4 className="font-semibold">Historial</h4>
            {history.length === 0 ? (
              <div className="text-muted">Sin movimientos</div>
            ) : (
              <ul className="list-disc pl-5">
                {history.map((h, i) => (
                  <li key={i}>{h.date || h.created_at} - {h.description || h.type || JSON.stringify(h)}</li>
                ))}
              </ul>
            )}
          </div>
        </div>

        <div className="flex justify-end gap-2 mt-4">
          <Button variant="outline" onClick={() => onOpenChange(false)}>Cerrar</Button>
          <Button onClick={() => { onOpenChange(false); onEdit(); }}>Editar</Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}
